 function calculate(){const n=(s,max=Infinity)=>Math.max(0,Math.min(max,Number($(s).value)||0)),cash=n('#base')*n('#months',24),long=cash+n('#bonus')+n('#equity'),first=long+n('#signon'),target=n('#salary-target');$('#offer-result').innerHTML=`<b>保证现金 ${cash.toFixed(1)} 万 / 年</b>含浮动部分的情景长期年包 ${long.toFixed(1)} 万；含签字费首年 ${first.toFixed(1)} 万。${cash>=target?'保证现金达到所选目标，仍需核对书面条款和工作方式。':`保证现金距目标差 ${(target-cash).toFixed(1)} 万，浮动奖金和股权需另看兑现条件。`}`;}
