 function exportJobs(list){const headers=['岗位参考ID','岗位名称','公司','名称状态','整理依据','关联原记录ID','岗位方向','男方参考匹配','女方参考匹配','公告地点（子岗待核）','公告薪资（子岗适用范围待核）','公告链接','投递入口','收藏','研究状态'];const records=list.map(r=>[r.id,r.title,r.company,typeNames[r.type],r.method,r.sourceIds,r.tracks.map(id=>trackMap.get(id)?.label||'摘要不足'),fitNames[r.male],fitNames[r.female],r.cities,r.salary,r.sourceIds.map(id=>rowById.get(id).announcement).filter(Boolean),r.sourceIds.map(id=>rowById.get(id).apply).filter(Boolean),saved[r.id]?'是':'否',progress[r.id]||'未标记']);download('2028岗位参考-筛选结果.csv','\uFEFF'+[headers,...records].map(x=>x.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
